select #{TRADE_FLOW_STATUS_01} as activeState, /*有效状态*/ wtfpdt.TOTLE_TRADE_ID as totleTradeId, /*汇总交易编号*/ wtfpdt.PS as ps, /*交易方向*/ to_char(wtfpdt.TRADE_DATE, 'yyyy-MM-dd') as tradeDate, /*交易日期*/ wtfpdt.SHARE_AMT as shareAmt, /*交易份额*/ wtfpdt.FPRICE_AMT as fpriceAmt, /*全价总额*/ bb.BOOKSET_ID as booksetId, /*账套代码*/ bb.BOOKSET_NAME as booksetName, /*账套名称*/ fri.BENCHMARK_ID as benchmarkId, /*基准编号*/ to_char(spo.SETTLE_DATE, 'yyyy-MM-dd') as settleDate, /*结算日期*/ fris.EXE_PRICE as exePrice, /*执行价格*/ ftra.OPT_FEE_PAY_TYPE as optFeePayType /*期权费支付类型*/ from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL wtfpdt left join PTL_TRADE pt on pt.PORTFOLIO_ID = wtfpdt.PORTFOLIO_ID left join BOK_DEAL_ACCOUNTING bda on bda.BUSI_NO = pt.BUSI_NO left join BOK_BOOKSET bb on bb.BOOKSET_ID = bda.BOOKSET_ID left join FIN_RATE_INFO fri on fri.FINPROD_ID = wtfpdt.FINPROD_ID left join STL_PAY_ORDERS spo on spo.TRADE_ID = wtfpdt.TOTLE_TRADE_ID left join FIN_RATE_INFO_STRUCTURE fris on fris.CASH_ID = wtfpdt.CASH_ID left join FIN_TRADE_PRODUCT_ADD ftra on ftra.FINPROD_ID = wtfpdt.FINPROD_ID where wtfpdt.IS_CANCEL != #{YES_OR_NO_Y} and wtfpdt.TRADE_STATUS = #{TRADE_STATUS_01} and wtfpdt.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F35}
AND bb.BOOKSET_ID = #{booksetId}
AND wtfpdt.TOTLE_TRADE_ID = #{totleTradeId}
AND fri.BENCHMARK_ID = #{benchmarkId}
AND wtfpdt.PS = #{ps}
AND ftra.OPT_FEE_PAY_TYPE = #{optFeePayType}
AND activeState = #{activeState}
AND wtfpdt.TRADE_DATE >=to_date(#{tradeDateStart},'yyyy-MM-dd')
AND wtfpdt.TRADE_DATE <=to_date(#{tradeDateEnd},'yyyy-MM-dd')
union select #{TRADE_FLOW_STATUS_02} as activeState, /*有效状态*/ tfpdt.TOTLE_TRADE_ID as totleTradeId, /*汇总交易编号*/ tfpdt.PS as ps, /*交易方向*/ to_char(tfpdt.TRADE_DATE, 'yyyy-MM-dd') as tradeDate, /*交易日期*/ tfpdt.SHARE_AMT as shareAmt, /*交易份额*/ tfpdt.FPRICE_AMT as fpriceAmt, /*全价总额*/ bb.BOOKSET_ID as booksetId, /*账套代码*/ bb.BOOKSET_NAME as booksetName, /*账套名称*/ fri.BENCHMARK_ID as benchmarkId, /*基准编号*/ to_char(spo.SETTLE_DATE, 'yyyy-MM-dd') as settleDate, /*结算日期*/ fris.EXE_PRICE as exePrice, /*执行价格*/ ftra.OPT_FEE_PAY_TYPE as optFeePayType /*期权费支付类型*/ from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt left join PTL_TRADE pt on pt.PORTFOLIO_ID = tfpdt.PORTFOLIO_ID left join BOK_DEAL_ACCOUNTING bda on bda.BUSI_NO = pt.BUSI_NO left join BOK_BOOKSET bb on bb.BOOKSET_ID = bda.BOOKSET_ID left join FIN_RATE_INFO fri on fri.FINPROD_ID = tfpdt.FINPROD_ID left join STL_PAY_ORDERS spo on spo.TRADE_ID = tfpdt.TOTLE_TRADE_ID left join FIN_RATE_INFO_STRUCTURE fris on fris.CASH_ID = tfpdt.CASH_ID left join FIN_TRADE_PRODUCT_ADD ftra on ftra.FINPROD_ID = tfpdt.FINPROD_ID where tfpdt.IS_CANCEL != #{YES_OR_NO_Y} and tfpdt.TRADE_STATUS = #{TRADE_STATUS_01} and tfpdt.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F35}
AND bb.BOOKSET_ID = #{booksetId}
AND tfpdt.TOTLE_TRADE_ID = #{totleTradeId}
AND fri.BENCHMARK_ID = #{benchmarkId}
AND tfpdt.PS = #{ps}
AND ftra.OPT_FEE_PAY_TYPE = #{optFeePayType}
AND activeState = #{activeState}
AND tfpdt.TRADE_DATE >=to_date(#{tradeDateStart},'yyyy-MM-dd')
AND tfpdt.TRADE_DATE <=to_date(#{tradeDateEnd},'yyyy-MM-dd')
union select #{TRADE_FLOW_STATUS_03} as activeState, /*有效状态*/ tfpdt.TOTLE_TRADE_ID as totleTradeId, /*汇总交易编号*/ tfpdt.PS as ps, /*交易方向*/ to_char(tfpdt.TRADE_DATE, 'yyyy-MM-dd') as tradeDate, /*交易日期*/ tfpdt.SHARE_AMT as shareAmt, /*交易份额*/ tfpdt.FPRICE_AMT as fpriceAmt, /*全价总额*/ bb.BOOKSET_ID as booksetId, /*账套代码*/ bb.BOOKSET_NAME as booksetName, /*账套名称*/ fri.BENCHMARK_ID as benchmarkId, /*基准编号*/ to_char(spo.SETTLE_DATE, 'yyyy-MM-dd') as settleDate, /*结算日期*/ fris.EXE_PRICE as exePrice, /*执行价格*/ ftra.OPT_FEE_PAY_TYPE as optFeePayType /*期权费支付类型*/ from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt left join PTL_TRADE pt on pt.PORTFOLIO_ID = tfpdt.PORTFOLIO_ID left join BOK_DEAL_ACCOUNTING bda on bda.BUSI_NO = pt.BUSI_NO left join BOK_BOOKSET bb on bb.BOOKSET_ID = bda.BOOKSET_ID left join FIN_RATE_INFO fri on fri.FINPROD_ID = tfpdt.FINPROD_ID left join STL_PAY_ORDERS spo on spo.TRADE_ID = tfpdt.TOTLE_TRADE_ID left join FIN_RATE_INFO_STRUCTURE fris on fris.CASH_ID = tfpdt.CASH_ID left join FIN_TRADE_PRODUCT_ADD ftra on ftra.FINPROD_ID = tfpdt.FINPROD_ID where tfpdt.IS_CANCEL = #{YES_OR_NO_Y} and tfpdt.TRADE_STATUS = #{TRADE_STATUS_01} and tfpdt.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F35}
AND bb.BOOKSET_ID = #{booksetId}
AND tfpdt.TOTLE_TRADE_ID = #{totleTradeId}
AND fri.BENCHMARK_ID = #{benchmarkId}
AND tfpdt.PS = #{ps}
AND ftra.OPT_FEE_PAY_TYPE = #{optFeePayType}
AND activeState = #{activeState}
